// Query for support on a random architecture or special feature.
// Prefer valid enums to avoid undefined behavior.
unsigned int pick = *FUZZ_PARAM(unsigned int);
int query;
switch (pick % 6) {
    case 0: query = CS_ARCH_ALL; break;
    case 1: query = CS_ARCH_X86; break;
    case 2: query = CS_ARCH_ARM; break;
    case 3: query = CS_ARCH_ARM64; break;
    case 4: query = CS_ARCH_MIPS; break;
    default: query = CS_ARCH_RISCV; break;
}
(void)cs_support(query);

// Enforce: handle must be previously opened and with no outstanding cs_insn allocations.
int is_open = FUZZ_GET_ATTR_INT(handle, "is_open");
if (!is_open) { FUZZ_BAIL(); }
int outstanding = FUZZ_GET_ATTR_INT(handle, "outstanding_insn");
if (outstanding != 0) { FUZZ_BAIL(); }
// Close and verify handle becomes 0.
cs_err err = cs_close(handle);
if (err != CS_ERR_OK) { FUZZ_BAIL(); }
FUZZ_ASSERT(*handle == 0, "cs_close did not zero the handle");
FUZZ_SET_ATTR_INT(handle, "is_open", 0);

// Randomly choose an option type and set a compatible value.
// For CS_OPT_MEM we pass a local cs_opt_mem and ignore the handle (per API it is allowed before open).
unsigned int pick = *FUZZ_PARAM(unsigned int);
cs_opt_type type;
size_t value = 0;
cs_err err;
if ((pick % 6) == 0) {
    type = CS_OPT_MEM;
    cs_opt_mem mem = {0}; // all callbacks NULL => use system allocators
    value = (size_t)&mem;
    err = cs_option(0, type, value);
} else if ((pick % 6) == 1) {
    // Toggle detail
    type = CS_OPT_DETAIL;
    cs_opt_value v = ((*FUZZ_PARAM(unsigned int) & 1u) ? CS_OPT_ON : CS_OPT_OFF);
    value = (size_t)v;
    err = cs_option(*handle, type, value);
    if (err == CS_ERR_OK) {
        FUZZ_SET_ATTR_INT(handle, "detail_on", v == CS_OPT_ON ? 1 : 0);
    }
} else if ((pick % 6) == 2) {
    // Syntax
    type = CS_OPT_SYNTAX;
    cs_opt_value syntaxes[] = { CS_OPT_SYNTAX_DEFAULT, CS_OPT_SYNTAX_INTEL, CS_OPT_SYNTAX_ATT, CS_OPT_SYNTAX_NOREGNAME, CS_OPT_SYNTAX_MASM, CS_OPT_SYNTAX_MOTOROLA };
    cs_opt_value v = syntaxes[*FUZZ_PARAM(unsigned int) % (sizeof(syntaxes)/sizeof(syntaxes[0]))];
    value = (size_t)v;
    err = cs_option(*handle, type, value);
} else if ((pick % 6) == 3) {
    // MODE change at runtime: pick a small compatible subset based on existing arch/mode
    type = CS_OPT_MODE;
    int arch = FUZZ_GET_ATTR_INT(handle, "arch");
    cs_mode new_mode = (cs_mode)0;
    unsigned int r = *FUZZ_PARAM(unsigned int);
    if (arch == CS_ARCH_X86) {
        if (r & 1u) new_mode = (cs_mode)(new_mode | CS_MODE_16);
        if (r & 2u) new_mode = (cs_mode)(new_mode | CS_MODE_32);
        if (r & 4u) new_mode = (cs_mode)(new_mode | CS_MODE_64);
    } else if (arch == CS_ARCH_ARM) {
        if (r & 1u) new_mode = (cs_mode)(new_mode | CS_MODE_ARM);
        if (r & 2u) new_mode = (cs_mode)(new_mode | CS_MODE_THUMB);
    }
    if (new_mode == 0) new_mode = (cs_mode)FUZZ_GET_ATTR_INT(handle, "mode");
    value = (size_t)new_mode;
    err = cs_option(*handle, type, value);
    if (err == CS_ERR_OK) FUZZ_SET_ATTR_INT(handle, "mode", (int)new_mode);
} else if ((pick % 6) == 4) {
    // Skipdata on/off
    type = CS_OPT_SKIPDATA;
    cs_opt_value v = ((*FUZZ_PARAM(unsigned int) & 1u) ? CS_OPT_ON : CS_OPT_OFF);
    value = (size_t)v;
    err = cs_option(*handle, type, value);
} else {
    // Unsigned immediates on/off
    type = CS_OPT_UNSIGNED;
    cs_opt_value v = ((*FUZZ_PARAM(unsigned int) & 1u) ? CS_OPT_ON : CS_OPT_OFF);
    value = (size_t)v;
    err = cs_option(*handle, type, value);
}
if (err != CS_ERR_OK) { FUZZ_BAIL(); }

// Verify handle looks valid before calling
if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
( void ) cs_errno(*handle);

// Map a random cs_err to string; API guarantees a static string pointer.
cs_err code = (cs_err)((int)(*FUZZ_PARAM(unsigned int) % 16));
const char *s = cs_strerror(code);
if (!s) { FUZZ_BAIL(); }

// Preconditions: valid open handle.
if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
// Prepare a random code buffer (size-limited for performance) and parameters.
std::string buf = FUZZ_PARAM_STR();
if (buf.size() == 0) { FUZZ_BAIL(); }
size_t max_len = 512;
if (buf.size() > max_len) buf.resize(max_len);
const uint8_t *code = reinterpret_cast<const uint8_t *>(buf.data());
size_t code_size = buf.size();
uint64_t address = ((uint64_t)*FUZZ_PARAM(unsigned int) << 32) | (uint64_t)*FUZZ_PARAM(unsigned int);
size_t count = (size_t)(*FUZZ_PARAM(unsigned int) % 32); // 0..31 (0 means decode as much as possible)
cs_insn *insn_array = nullptr;
size_t n = cs_disasm(*handle, code, code_size, address, count, &insn_array);
if (n == 0 || insn_array == nullptr) {
    // On failure we cannot keep any allocation; do not update outstanding_insn
    FUZZ_BAIL();
}
// Track allocation size on the handle so cs_close can enforce no leaks.
int out = FUZZ_GET_ATTR_INT(handle, "outstanding_insn");
FUZZ_SET_ATTR_INT(handle, "outstanding_insn", out + (int)n);
// Mark the array with ownership info: it's an array with 'n' items belonging to this handle.
FUZZ_SET_ATTR_INT(insn_array, "is_array", 1);
FUZZ_SET_ATTR_INT(insn_array, "count", (int)n);
FUZZ_SET_ATTR_PTR(insn_array, "parent_handle", (void*)handle);
// If detail is ON, mark that details may be available (required by some APIs).
int detail_on = FUZZ_GET_ATTR_INT(handle, "detail_on");
FUZZ_SET_ATTR_INT(insn_array, "has_detail", detail_on ? 1 : 0);

// Determine whether this was an array or a single cs_insn and free accordingly.
int count = FUZZ_GET_ATTR_INT(insn, "count");
if (count <= 0) { FUZZ_BAIL(); }
// Fetch parent handle (if tracked) to adjust outstanding counter.
csh *parent = (csh*)FUZZ_GET_ATTR_PTR(insn, "parent_handle");
cs_free(insn, (size_t)count);
if (parent) {
    int out = FUZZ_GET_ATTR_INT(parent, "outstanding_insn");
    FUZZ_SET_ATTR_INT(parent, "outstanding_insn", out - count);
}
// Drop the insn by not returning it.

// Preconditions: valid open handle.
if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
cs_insn *insn = cs_malloc(*handle);
if (!insn) { FUZZ_BAIL(); }
// Track as a single allocation associated with this handle.
int out = FUZZ_GET_ATTR_INT(handle, "outstanding_insn");
FUZZ_SET_ATTR_INT(handle, "outstanding_insn", out + 1);
FUZZ_SET_ATTR_INT(insn, "is_array", 0);
FUZZ_SET_ATTR_INT(insn, "count", 1);
FUZZ_SET_ATTR_PTR(insn, "parent_handle", (void*)handle);
// For iter use, detail availability depends on handle option.
FUZZ_SET_ATTR_INT(insn, "has_detail", FUZZ_GET_ATTR_INT(handle, "detail_on"));

// Preconditions:
// - handle must be valid
// - insn must be previously allocated by cs_malloc(handle)
if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(insn, "count") != 1) { FUZZ_BAIL(); }
// Prepare a buffer and iterate a single step to exercise API.
std::string buf = FUZZ_PARAM_STR();
if (buf.empty()) { FUZZ_BAIL(); }
if (buf.size() > 256) buf.resize(256);
const uint8_t *code = reinterpret_cast<const uint8_t *>(buf.data());
size_t size = buf.size();
uint64_t address = ((uint64_t)*FUZZ_PARAM(unsigned int) << 32) | (uint64_t)*FUZZ_PARAM(unsigned int);
bool ok = cs_disasm_iter(*handle, &code, &size, &address, insn);
// ok may be false; that's fine. The function updates pointers on success.
( void ) ok;

if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
unsigned int reg_id = *FUZZ_PARAM(unsigned int);
( void ) cs_reg_name(*handle, reg_id);

if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
unsigned int insn_id = *FUZZ_PARAM(unsigned int);
( void ) cs_insn_name(*handle, insn_id);

if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
unsigned int group_id = *FUZZ_PARAM(unsigned int);
( void ) cs_group_name(*handle, group_id);

// Requires detail enabled; irrelevant in DIET mode.
if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(handle, "detail_on")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(insn, "has_detail")) { FUZZ_BAIL(); }
unsigned int group_id = *FUZZ_PARAM(unsigned int);
( void ) cs_insn_group(*handle, insn, group_id);

if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(handle, "detail_on")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(insn, "has_detail")) { FUZZ_BAIL(); }
unsigned int reg_id = *FUZZ_PARAM(unsigned int);
( void ) cs_reg_read(*handle, insn, reg_id);

if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(handle, "detail_on")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(insn, "has_detail")) { FUZZ_BAIL(); }
unsigned int reg_id = *FUZZ_PARAM(unsigned int);
( void ) cs_reg_write(*handle, insn, reg_id);

if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(handle, "detail_on")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(insn, "has_detail")) { FUZZ_BAIL(); }
unsigned int op_type = *FUZZ_PARAM(unsigned int);
int cnt = cs_op_count(*handle, insn, op_type);
if (cnt < -1) { FUZZ_BAIL(); }

if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(handle, "detail_on")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(insn, "has_detail")) { FUZZ_BAIL(); }
unsigned int op_type = *FUZZ_PARAM(unsigned int);
int cnt = cs_op_count(*handle, insn, op_type);
if (cnt <= 0) { FUZZ_BAIL(); }
unsigned int position = (unsigned int)(*FUZZ_PARAM(unsigned int) % (unsigned int)cnt) + 1u;
int idx = cs_op_index(*handle, insn, op_type, position);
if (idx < -1) { FUZZ_BAIL(); }

// Requires detail enabled and valid insn from disasm/disasm_iter.
if (!FUZZ_GET_ATTR_INT(handle, "is_open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(handle, "detail_on")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(insn, "has_detail")) { FUZZ_BAIL(); }
cs_regs regs_read = {0};
cs_regs regs_write = {0};
uint8_t regs_read_count = 0, regs_write_count = 0;
cs_err err = cs_regs_access(*handle, insn, regs_read, &regs_read_count, regs_write, &regs_write_count);
if (err != CS_ERR_OK && err != CS_ERR_DIET) {
    FUZZ_BAIL();
}

// Query version; optionally retrieve major/minor via local variables or NULL.
// Avoid FUZZ_PARAM on pointer types per runtime constraints.
int use_major = (*FUZZ_PARAM(unsigned int) & 1u);
int use_minor = (*FUZZ_PARAM(unsigned int) & 1u);
int major_local = 0, minor_local = 0;
int *major_ptr = use_major ? &major_local : nullptr;
int *minor_ptr = use_minor ? &minor_local : nullptr;
unsigned int packed = cs_version(major_ptr, minor_ptr);
// Basic property: when both pointers are provided, packed encodes major<<8 | minor.
if (major_ptr && minor_ptr) {
    unsigned int expect = ((unsigned int)major_local << 8) | ((unsigned int)minor_local & 0xFFu);
    FUZZ_ASSERT(packed == expect, "cs_version packed encoding mismatch");
}
// Validation: stub respects optional NULL out-params and asserts encoding only when both are provided.

// Choose a valid architecture and a compatible mode bitmask.
cs_arch archs[] = { CS_ARCH_X86, CS_ARCH_ARM, CS_ARCH_ARM64, CS_ARCH_MIPS, CS_ARCH_RISCV };
cs_arch arch = archs[*FUZZ_PARAM(unsigned int) % (sizeof(archs)/sizeof(archs[0]))];
cs_mode mode = (cs_mode)0;
switch (arch) {
    case CS_ARCH_X86: {
        unsigned int r = *FUZZ_PARAM(unsigned int);
        if (r & 1u) mode = (cs_mode)(mode | CS_MODE_16);
        if (r & 2u) mode = (cs_mode)(mode | CS_MODE_32);
        if (r & 4u) mode = (cs_mode)(mode | CS_MODE_64);
        if (r & 8u) mode = (cs_mode)(mode | CS_MODE_BIG_ENDIAN); // mostly ignored on x86
        break;
    }
    case CS_ARCH_ARM: {
        unsigned int r = *FUZZ_PARAM(unsigned int);
        if (r & 1u) mode = (cs_mode)(mode | CS_MODE_ARM);
        if (r & 2u) mode = (cs_mode)(mode | CS_MODE_THUMB);
        if (r & 4u) mode = (cs_mode)(mode | CS_MODE_MCLASS);
        if (r & 8u) mode = (cs_mode)(mode | CS_MODE_V8);
        break;
    }
    case CS_ARCH_ARM64: {
        unsigned int r = *FUZZ_PARAM(unsigned int);
        if (r & 1u) mode = (cs_mode)(mode | CS_MODE_V8);
        break;
    }
    case CS_ARCH_MIPS: {
        unsigned int r = *FUZZ_PARAM(unsigned int);
        if (r & 1u) mode = (cs_mode)(mode | CS_MODE_MIPS32);
        if (r & 2u) mode = (cs_mode)(mode | CS_MODE_MIPS64);
        if (r & 4u) mode = (cs_mode)(mode | CS_MODE_MIPS3);
        if (r & 8u) mode = (cs_mode)(mode | CS_MODE_MIPS2);
        break;
    }
    case CS_ARCH_RISCV: {
        unsigned int r = *FUZZ_PARAM(unsigned int);
        if (r & 1u) mode = (cs_mode)(mode | CS_MODE_RISCV32);
        if (r & 2u) mode = (cs_mode)(mode | CS_MODE_RISCV64);
        if (r & 4u) mode = (cs_mode)(mode | CS_MODE_RISCVC);
        break;
    }
    default: break;
}
// Ensure at least a typical baseline mode to reduce CS_ERR_MODE.
if (arch == CS_ARCH_X86 && mode == 0) mode = CS_MODE_32;
if (arch == CS_ARCH_ARM && mode == 0) mode = CS_MODE_ARM;

csh h = 0;
cs_err err = cs_open(arch, mode, &h);
if (err != CS_ERR_OK || h == 0) { FUZZ_BAIL(); }
// Create an output handle object (user-managed storage for the opaque size_t handle value).
csh *handle = new csh; // persistent object returned to the pool
*handle = h;
// Mark attributes for downstream APIs and lifetime enforcement.
FUZZ_SET_ATTR_INT(handle, "is_open", 1);
FUZZ_SET_ATTR_INT(handle, "detail_on", 0);
FUZZ_SET_ATTR_INT(handle, "outstanding_insn", 0);
FUZZ_SET_ATTR_INT(handle, "arch", (int)arch);
FUZZ_SET_ATTR_INT(handle, "mode", (int)mode);
// Validation: stub avoids FUZZ_PARAM on pointer types, ensures compatible arch/mode, and returns a non-null initialized handle object.
